  selector: 'app-pager',
  standalone: true,
  imports: [SlicePipe],
  template: `
    @for (item of items() | slice: start(): start() + 3; track item) {
      <span>{{ item }}</span>
    }
  `,
})
export class PagerComponent {
  items = signal(['a', 'b', 'c', 'd', 'e']);
  page = signal(0);
  start = computed(() => this.page() * 3);
}

