import { fakeAsync, tick } from '@angular/core/testing';
import { delay, of } from 'rxjs';

describe('DelayedLoader', () => {
  it('resolves after delay', fakeAsync(() => {
    let value = '';
    of('done').pipe(delay(1000)).subscribe(v => (value = v));
    tick(1000);
    expect(value).toBe('done');
  }));
});

